const rawData = $input.first().json;

const totalEventos = rawData.nombre?.length || 0;
const results = [];

for (let i = 0; i < totalEventos; i++) {

  const nombre = rawData.nombre[i]?.trim() || "Sin nombre";
  const lugar = rawData.lugar?.[i]?.trim() || "Tucumán";
  const categoria = rawData.categoria?.[i]?.trim() || "General";
  const hora = rawData.hora?.[i]?.trim() || "A confirmar";

  // Limpio la fecha que viene con saltos de línea (\n) según se ve en la captura
  const fechaCruda = rawData.fecha_cruda?.[i] || "";
  const fechaLimpia = fechaCruda.replace(/\s+/g, ' ').trim();

  // Genero un fingerprint para evitar duplicados
  const fingerprint = `${nombre}-${lugar}-${fechaLimpia}`
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "") // Quitamos acentos
    .replace(/[^a-z0-9]/g, '-');

  results.push({
    json: {
      nombre,
      lugar,
      categoria,
      hora,
      fecha_evento: fechaLimpia,
      fingerprint,
      fecha_obtencion: new Date().toISOString(),
      fuente: "Agenda Tucumán"
    }
  });
}

return results;

function slugify(str = "") {
  return str
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "") // quitar tildes
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
}

// 👉 parsea "May 05 14:00" → "2026-05-05T14:00:00Z"
function parseFecha(fechaStr = "") {
  const meses = {
    Jan: "01", Feb: "02", Mar: "03", Apr: "04",
    May: "05", Jun: "06", Jul: "07", Aug: "08",
    Sep: "09", Oct: "10", Nov: "11", Dec: "12"
  };

  try {
    const parts = fechaStr.split(" "); // ["May", "05", "14:00"]
    const mes = meses[parts[0]];
    const dia = parts[1]?.padStart(2, "0");
    const hora = parts[2] || "00:00";

    if (!mes || !dia) return null;

    return `2026-${mes}-${dia}T${hora}:00Z`;
  } catch {
    return null;
  }
}

return items.flatMap(item => {
  try {
    // 1. tomar el string del LLM
    let raw = item.json.text;

    // 2. parsear JSON string → objeto
    const parsed = JSON.parse(raw);

    // 3. mapear y generar fingerprint + fecha parseada
    return parsed.map(event => {
      const nombre = event.nombre_limpio || "";
      const lugar = event.lugar || "";
      const fechaRaw = event.fecha_hora || "";

      const fechaISO = parseFecha(fechaRaw); 

const soloFecha = fechaISO ? fechaISO.split('T')[0] : "sin-fecha";


const fingerprint = `${slugify(nombre)}-${slugify(lugar)}-${soloFecha}`;
      return {
        json: {
          nombre,
          lugar,
          categoria: event.categoria|| null,
          descripcion: event.descripcion || null,
          fecha_evento: fechaISO, // ✅ ahora timestamp válido
          fingerprint,
          fuente: "Agenda Tucumán"
        }
      };
    });

  } catch (e) {
    return [{
      json: {
        error: "parse_error",
        raw: item.json.text
      }
    }];
  }
});
